export function typstPageSetup(payload: ExportPayload): string {
  const layout = payload.layout ?? DEFAULT_LAYOUT;
  const page = resolvePageSetup(layout);
  const margin = Object.entries(resolveMargins(layout))
    .map(
      ([key, value]) =>
        // The editor's small screen gutters are not enough for a framed page.
        // Reserve room for the frame and running furniture; larger chosen
        // margins still apply unchanged.
        `${key}: ${Math.max(key === "top" || key === "bottom" ? 54 : 36, Math.min(8, Math.max(0, Number.isFinite(value) ? value : 0)) * 12)}pt`,
    )
    .join(", ");
  const header = payload.header || (layout.runningHeader ? payload.title : "");
  // Clear the frame behind running furniture, like labels printed into a rule.
  const furniture = (body: string) =>
    `#box(fill: rgb("#fbf6e7"), inset: (x: 3pt))[${body}]`;
  const footer = [
    payload.footer ? furniture(`#text(${typstString(payload.footer)})`) : "",
    layout.pageNumbers
      ? `#h(1fr)${furniture('#context counter(page).display("1")')}`
      : "",
  ]
    .filter(Boolean)
    .join(" ");
  return [
    `#set document(title: ${typstString(payload.title)})`,
    TYPST_EDITORIAL_STYLES,
    `#set page(width: ${page.widthIn}in, height: ${page.heightIn}in, margin: (${margin}), fill: rgb("#fbf6e7"), background: align(center + horizon, rect(width: 100% - 36pt, height: 100% - 36pt, stroke: 0.6pt + rgb("#cabb9d"))), header-ascent: 20%, footer-descent: 20%, header: [${header ? `#set text(font: "Special Elite", size: 8pt, fill: rgb("#4a3f33"))\n#set par(justify: false)\n${furniture(`#text(${typstString(header)})`)}` : ""}], footer: [${footer ? `#set text(font: "Special Elite", size: 8pt, fill: rgb("#4a3f33"))\n#set par(justify: false)\n${footer}` : ""}])`,
  ].join("\n\n");
}

