item.stdout:
/* The opening glyph remains manuscript text. Its transparent engraving is a
 * view-only background; slow/missing artwork keeps the ordinary drop cap. */
.twyne-editor
  .ProseMirror
  > p:first-of-type:not(.twyne-illuminated-paragraph)::first-letter,
.twyne-editor .ProseMirror .twyne-illuminated-initial {
  font-family: inherit;
  font-weight: 700;
  font-size: min(4.2em, 5rem);
  float: left;
  line-height: 0.85;
  margin: 0.08em 0.12em -0.05em 0;
  color: var(--color-vermilion);
}

.twyne-editor .ProseMirror .twyne-illuminated-initial {
  text-indent: 0;
  text-decoration: none;
  caret-color: var(--color-vermilion);
}

.twyne-editor .ProseMirror .twyne-illuminated-initial.is-illuminated {
  width: 1.16em;
  height: 1.16em;
  margin: 0.035em 0.14em 0.02em 0;
  background-image: var(--twyne-initial-artwork);
  background-size: contain;
  background-position: center;
  background-repeat: no-repeat;
  color: transparent;
  -webkit-text-fill-color: transparent;
  text-shadow: none;
}

.twyne-editor .ProseMirror .twyne-illuminated-initial::selection {
  background-color: var(--color-vermilion-light, #c1272d30);
}

@media (forced-colors: active) {
  .twyne-editor .ProseMirror .twyne-illuminated-initial.is-illuminated {
    background-image: none;
    color: CanvasText;
    -webkit-text-fill-color: CanvasText;
  }
}

@media print {
  /* Printing may omit backgrounds: the actual opening letter must survive. */
  .twyne-editor .ProseMirror .twyne-illuminated-initial.is-illuminated {
    background-image: none;
    color: var(--color-ink);
    -webkit-text-fill-color: var(--color-ink);
  }
}

