import { resolveOpeningInitial, type LayoutSettings } from "../types";
import { illuminatedInitialArtwork, openingInitial } from "./illuminated-initials";

/** Decorate a throwaway print DOM. The stored manuscript is never rewritten. */
export function decoratePrintedOpening(html: string, layout: LayoutSettings): string {
  const settings = resolveOpeningInitial(layout);
  if (settings.mode === "off" || typeof DOMParser === "undefined") return html;
  const doc = new DOMParser().parseFromString(html, "text/html");
  // XML-only parsers used by import tools cannot safely rewrite an HTML range.
  if (!doc.body?.children || !doc.createRange) return html;
  const paragraph = Array.from(doc.body.children).find(el => el.tagName === "P");
  if (!paragraph) return html;
  const textNodes = (): Text[] => {
    const nodes: Text[] = [];
    const walk = (node: Node) => {
      if (node.nodeType === 3) nodes.push(node as Text);
      else for (const child of Array.from(node.childNodes)) walk(child);
    };
    walk(paragraph);
    return nodes;
  };
  // An atom before text is not a prose opening.
  if (paragraph.querySelector("img, br, [data-type='inline-math']")?.compareDocumentPosition(textNodes()[0]) === 4) return html;
  const initial = openingInitial(paragraph.textContent ?? "");
  if (!initial) return html;
  const wrap = (from: number, to: number, className: string) => {
    const range = doc.createRange();
    let offset = 0;
    let started = false;
    for (const node of textNodes()) {
      const end = offset + node.length;
      if (!started && from < end) {
        range.setStart(node, from - offset);
        started = true;
      }
      if (started && to <= end) {
        range.setEnd(node, to - offset);
        const span = doc.createElement("span");
        span.className = className;
        span.append(range.extractContents());
        range.insertNode(span);
        return span;
      }
      offset = end;
    }
    return null;
  };
  if (initial.from) wrap(0, initial.from, "export-initial-prefix");
  const cap = wrap(initial.from, initial.to, "export-initial");
  const artwork = settings.mode === "illuminated"
    ? illuminatedInitialArtwork(initial.glyph, settings.collection)
    : null;
  if (cap && artwork) {
    // Use a real image: the print preparation can await decoding, and a PDF
    // retains the engraving even when 'background graphics' is disabled.
    const image = doc.createElement("img");
    image.src = typeof window === "undefined" ? artwork : new URL(artwork, window.location.href).href;
    image.alt = initial.glyph;
    image.className = "export-initial-artwork";
    cap.replaceChildren(image);
  }
  return doc.body.innerHTML;
}

export function printedInitialStyles(layout: LayoutSettings): string {
  const settings = resolveOpeningInitial(layout);
  const size = { small: "3em", medium: "4.2em", large: "5.5em" }[settings.size];
  const cap = { small: "3.5rem", medium: "5rem", large: "6.5rem" }[settings.size];
  return `
  .export-initial { float: left; font-size: min(${size}, ${cap}); line-height: .85; font-weight: 700; color: #c1272d; margin: .06em .12em .02em 0; }
  .export-initial-prefix { float: left; font-size: 1.4em; line-height: 1; margin-right: .08em; }
  .export-initial-artwork { display: block; width: 1.16em; height: 1.16em; object-fit: contain; }
  `;
}
import { resolvePageBorder, type LayoutSettings } from "../types";

export function pageBorderArtwork(layout: LayoutSettings): string | null {
  const border = resolvePageBorder(layout);
  return border === "none" || border === "plain"
    ? null
    : `/assets/page-borders/${border}.webp`;
}

export function hasOrnateBorder(layout: LayoutSettings): boolean {
  return pageBorderArtwork(layout) !== null;
}

