        ? `${normalized}</body>`
        : `${normalized.slice(0, htmlClose)}</body>${normalized.slice(htmlClose)}`;
  }
  if (/<html(?:\s|>)/i.test(normalized) && !/<\/html\s*>/i.test(normalized)) {
    normalized += "</html>";
  }
  return normalized;
}

